// Variant A: existing play shell, real casting records, no synthetic progress.
let dubbingCastingPlayback=null;
const dubbingCastingKinds=[['original','내 원작'],['recording','참여 중인 녹음'],['produced','내 제작 완성작'],['acted','내 출연작']];
function castingArt(p){return AifectDubbing.dubbingGenreArtwork(p.genres||p.options?.genres);}
function castingAvatar(m){return `<span class="dc-avatar">${avatarImage({id:m.profile_id,name:m.name,image_version:m.image_version},'producer',false)}</span>`;}
function dubbingCastingHTML(view){
 return `<div class="dc-browser"><section class="dc-catalog" aria-label="대본 목록"><header><h2>스크립트 작품 목록 <small>${view.items.length}${view.nextOffset!==null?' +':''}</small></h2><label><span class="sr-only">목록 정렬</span><select id="dc-sort"><option value="latest">최신순</option><option value="title">제목순</option></select></label></header><div class="dc-scripts">${view.items.map(p=>`<article class="dc-script" data-dc-row="${esc(p.id)}"><button type="button" data-dc-select="${esc(p.id)}" aria-pressed="false"><img src="${castingArt(p)}" alt="" width="64" height="64"><span><strong>${esc(p.title)}</strong><small>${esc(p.ownerName)}</small><span class="dc-script-meta">${icon('mic')} ${p.roleCount}개 배역 <em>참여 조합 보기</em></span></span></button><a class="small-button" href="#dubbing/${esc(p.id)}" aria-label="${esc(p.title)} 상세보기">상세보기 ${icon('chevron')}</a></article>`).join('')}</div></section><section class="dc-workspace" id="dc-workspace" aria-label="선택한 대본의 참여 조합" aria-live="polite"><p class="dc-note">대본을 선택하면 참여 조합을 볼 수 있어요.</p></section></div>`;
}
function castingStageHTML(state){
 const {data,stage,selected}=state,root=data.root,progress=data.combinations.filter(c=>c.state!=='complete'),counts=[...new Set(progress.map(c=>c.count))].sort((a,b)=>b-a),choices=progress.filter(c=>c.count===stage);
 return `<header class="dc-work-header"><img src="${castingArt(root)}" alt="" width="64" height="64"><div><h2>${esc(root.title)}</h2><p>${esc(root.ownerName)} <span>${icon('users')} ${root.roleCount}개 배역</span></p></div><a class="small-button" href="#dubbing/${esc(root.id)}">작품 상세보기 ${icon('arrow')}</a></header>
 <div class="dc-section-heading"><h3>참여 중인 조합</h3>${data.baseReady?'<button class="small-button" data-dc-base>'+icon('ui-plus-action')+' 새 조합 시작</button>':''}</div>
 ${counts.length?`<div class="dc-stage-tabs" role="tablist" aria-label="참여 인원별 조합">${counts.map(n=>`<button type="button" role="tab" tabindex="${n===stage?0:-1}" aria-selected="${n===stage}" data-dc-stage="${n}"><b>${n}/${root.roleCount}</b><span>${n===1?'원작자 기본':progress.filter(c=>c.count===n).length+'개 조합'}</span></button>`).join('')}</div><div class="dc-choices" aria-label="조합 선택">${choices.map((c,i)=>`<button type="button" class="dc-choice" data-dc-combo="${esc(c.id)}" aria-pressed="${selected===c.id}"><strong>${c.base?'원작자 기본 녹음':'조합 '+(i+1)}</strong><span class="dc-members">${c.members.map(m=>`<span>${castingAvatar(m)}<span><b>${esc(m.name)}${m.account_type==='ai_bot'?' <span class="ai-account-badge">AI</span>':''}</b><small>${esc(root.roles.find(r=>r.id===m.roleId)?.name||'')}</small></span></span>`).join('')}</span>${c.expiresAt?'<small>추가 참여가 없으면 '+new Date(c.expiresAt*1000).toLocaleDateString('ko-KR')+' 만료</small>':'<small>새 조합의 시작점 · 항상 유지</small>'}</button>`).join('')}</div><div id="dc-combination-body"></div>`:`<div class="dc-note"><h3>원작자의 첫 목소리를 기다려요</h3><p>원작자가 한 배역의 녹음을 공개하면 참여할 수 있어요.</p>${root.isOwner?`<a class="primary-button" href="#dubbing/${esc(root.id)}">내 배역 선택·녹음</a>`:''}</div>`}
 <footer class="dc-footnote">모든 배역이 모이면 완성된 더빙으로 이동해요. <a href="#karaoke/browse?tab=latest&type=dubbing">완성된 더빙 보기 ${icon('chevron')}</a></footer>`;
}
function castingLinesHTML(lines){return lines.length?`<div class="dc-lines">${lines.map((l,i)=>`<div class="dc-line"><span class="dc-line-index">${String(i+1).padStart(2,'0')}</span><button type="button" class="list-action" data-dc-audio="${esc(l.audioUrl)}" aria-label="${esc(l.roleName)} 대사 재생" aria-pressed="false">${icon('ui-play-action')}</button><span><b>${esc(l.roleName)}</b><span>${esc(l.text)}</span></span><small>${time(l.duration)}</small></div>`).join('')}</div>`:'<p class="dc-note">공개된 녹음 대사가 아직 없어요.</p>';}
function castingBodyHTML(state,detail){
 const roles=state.data.root.roles,empty=roles.filter(r=>!detail.members.some(m=>m.roleId===r.id)),lines=detail.lines.filter(l=>l.audioUrl);
 return `<div class="dc-bottom"><section><div class="dc-section-heading"><h3>대사 미리듣기</h3><small>${lines.length}개의 녹음</small></div><p class="dc-help">녹음된 대사를 한 줄씩 들어보세요.</p>${castingLinesHTML(lines)}</section><section><div class="dc-section-heading"><h3>빈 배역 선택</h3><small>${empty.length}개 배역</small></div><div class="dc-roles">${empty.map((r,i)=>`<label class="dc-role"><input type="radio" name="dc-role" value="${esc(r.id)}" ${i===0?'checked':''}><span class="dc-role-letter">${String.fromCharCode(65+roles.indexOf(r))}</span><span><b>${esc(r.name)} (${AifectDubbing.dubbingGenderLabel(r.gender)})</b><small>${esc(r.personality)}</small></span></label>`).join('')}</div>${empty.length?`<button type="button" class="primary-button dc-record" data-dc-record>${icon('mic')} 선택한 배역 녹음하기</button><p class="dc-help">공개 제출 시 빈 배역을 확정해요. 녹음 중에는 개인 초안으로 저장됩니다.</p>`:'<p class="dc-help">모든 배역이 모인 조합입니다.</p>'}<p class="dc-feedback" role="status"></p></section></div>`;
}
function stopCastingAudio(){if(dubbingCastingPlayback){dubbingCastingPlayback.pause();dubbingCastingPlayback=null;}document.querySelectorAll('[data-dc-audio][aria-pressed="true"]').forEach(b=>{b.setAttribute('aria-pressed','false');b.innerHTML=icon('ui-play-action');});}
function bindCastingAudio(root){root.querySelectorAll('[data-dc-audio]').forEach(b=>b.onclick=async()=>{
 const was=b.getAttribute('aria-pressed')==='true';stopCastingAudio();if(was)return;
 const audio=new Audio(b.dataset.dcAudio);dubbingCastingPlayback=audio;b.setAttribute('aria-pressed','true');b.innerHTML=icon('pause');audio.onended=stopCastingAudio;
 try{await audio.play();}catch{stopCastingAudio();toast('녹음 파일을 재생하지 못했어요. 다시 확인해주세요.');}
});}
window.addEventListener('hashchange',stopCastingAudio);
function bindDubbingCasting(view,container){
 const panel=container.querySelector('#dc-workspace');if(!panel)return;const state={ticket:0,detailTicket:0};
 async function selectCombo(id){
  stopCastingAudio();state.selected=id;const ticket=++state.detailTicket,project=state.data.root.id;
  panel.querySelectorAll('[data-dc-combo]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.dcCombo===id));
  const body=panel.querySelector('#dc-combination-body');body.innerHTML='<p class="dc-note" role="status">녹음을 불러오는 중…</p>';
  try{const detail=await api('/api/dubbing/casting/'+id+'/lines','GET',undefined,{fresh:true});if(!panel.isConnected||ticket!==state.detailTicket||project!==state.data.root.id)return;body.innerHTML=castingBodyHTML(state,detail);bindCastingAudio(body);
   body.querySelector('[data-dc-record]')?.addEventListener('click',async event=>{if(!me){askLogin();return;}const button=event.currentTarget,role=body.querySelector('[name="dc-role"]:checked')?.value;if(!role)return;button.disabled=true;try{const result=await api('/api/dubbing/casting/'+project+'/start','POST',{id:crypto.randomUUID(),targetId:id,roleId:role});location.hash='dubbing/'+result.projectId+'?record=1';}catch(e){body.querySelector('.dc-feedback').textContent=e.message;button.disabled=false;}});
  }catch(e){if(ticket===state.detailTicket&&body.isConnected)body.innerHTML=`<p class="dc-note" role="alert">${esc(e.message)}</p>`;}
 }
 function paintStage(n){state.stage=n;const c=state.data.combinations.find(c=>c.count===n&&c.state!=='complete');state.selected=c?.id;panel.innerHTML=castingStageHTML(state);panel.querySelectorAll('[data-dc-stage]').forEach(b=>{
  b.onclick=()=>paintStage(Number(b.dataset.dcStage));
  b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...panel.querySelectorAll('[data-dc-stage]')],index=tabs.indexOf(b),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowLeft'?-1:1)+tabs.length)%tabs.length,value=tabs[next].dataset.dcStage;paintStage(Number(value));panel.querySelector('[data-dc-stage="'+value+'"]').focus();};
 });panel.querySelector('[data-dc-base]')?.addEventListener('click',()=>paintStage(1));panel.querySelectorAll('[data-dc-combo]').forEach(b=>b.onclick=()=>selectCombo(b.dataset.dcCombo));if(c)void selectCombo(c.id);}
 async function select(id){const ticket=++state.ticket;++state.detailTicket;stopCastingAudio();container.querySelectorAll('[data-dc-select]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.dcSelect===id));panel.setAttribute('aria-busy','true');panel.innerHTML='<p class="dc-note">참여 조합을 불러오는 중…</p>';try{const data=await api('/api/dubbing/casting/'+id,'GET',undefined,{fresh:true});if(ticket!==state.ticket||!panel.isConnected)return;state.data=data;paintStage(Math.max(1,...data.combinations.filter(c=>c.state!=='complete').map(c=>c.count)));}catch(e){if(ticket===state.ticket)panel.innerHTML=`<p class="dc-note" role="alert">${esc(e.message)}</p>`;}finally{if(ticket===state.ticket)panel.removeAttribute('aria-busy');}}
 container.querySelectorAll('[data-dc-select]').forEach(b=>b.onclick=()=>select(b.dataset.dcSelect));
 container.querySelector('#dc-sort').onchange=e=>{const order=e.target.value==='title'?[...view.items].sort((a,b)=>a.title.localeCompare(b.title,'ko')):view.items;const list=container.querySelector('.dc-scripts');for(const p of order)list.append(list.querySelector('[data-dc-row="'+CSS.escape(p.id)+'"]'));};
 const desired=new URLSearchParams(location.hash.split('?')[1]).get('project');if(view.items.length)void select(view.items.some(p=>p.id===desired)?desired:view.items[0].id);
}
function castingMineTabs(kind){return `<nav class="dc-mine-tabs" aria-label="내 더빙 관계">${dubbingCastingKinds.map(([k,l])=>`<a class="small-button" ${kind===k?'aria-current="page"':''} href="#karaoke/dubbing?tab=mine&kind=${k}">${l}</a>`).join('')}</nav>`;}
function castingDetailHTML(p){
 const s=p.script,mine=p.roles.find(r=>r.mine),combo=p.casting?.combination;
 return `<a class="dubbing-back" href="#karaoke/dubbing?tab=discover&project=${esc(p.rootId)}">← 작품찾기</a><header class="dubbing-heading"><span class="eyebrow">${esc(s.genres.join(' · '))} · ${p.visibility==='private'?'비공개':combo?(p.state==='complete'?'완성된 더빙':'참여 중인 더빙'):'원작 대본'}</span><h1>${esc(p.title)}</h1><p>${esc(p.ownerName)} · ${s.roles.length}개 배역 · ${time(p.duration)}</p></header>
 ${combo?'<section class="dubbing-panel dc-complete-preview" id="dc-complete-preview"><p>녹음을 불러오는 중…</p></section>':''}
 <div class="dubbing-detail-layout"><section class="dubbing-panel dubbing-script-reader"><div class="dubbing-section-heading"><h2>캐릭터별 대본</h2><span>${s.lines.length}개 대사</span></div><nav class="dc-detail-filter" aria-label="대본 배역 필터"><button class="small-button" data-dc-filter="all" aria-pressed="true">전체</button>${s.roles.map(r=>`<button class="small-button" data-dc-filter="${esc(r.id)}" aria-pressed="false">${esc(r.name)}</button>`).join('')}</nav>${s.lines.map((l,i)=>`<article class="dubbing-reader-line dubbing-cast-${s.roles.findIndex(r=>r.id===l.roleId)%6}" data-dc-role-line="${esc(l.roleId)}"><span class="dubbing-line-number">${String(i+1).padStart(2,'0')}</span><div><small>${esc(s.scenes.find(sc=>sc.id===l.sceneId)?.title||'')} · ${esc([l.emotion,l.direction].filter(Boolean).join(' · '))}</small>${dubbingCueHTML(s,l.id)}<p><b>${esc(s.roles.find(r=>r.id===l.roleId)?.name)}: </b>${esc(l.text)}</p></div></article>`).join('')}</section>
 <aside><section class="dubbing-panel"><h2>배역 소개</h2><div class="dubbing-roles">${p.roles.map((r,i)=>`<article class="dubbing-role"><span class="dubbing-role-avatar">${String.fromCharCode(65+i)}</span><div><h3>${esc(r.name)} (${AifectDubbing.dubbingGenderLabel(r.gender)})</h3><p>${esc(r.personality)}</p>${r.participant?`<small>${esc(r.participant)}</small>`:''}${p.isOwner&&!combo&&!mine?`<button class="small-button" data-dubbing-claim="${esc(r.id)}" ${r.claimed||p.visibility!=='public'?'disabled':''}>이 배역 녹음</button>`:''}</div></article>`).join('')}</div>${!combo?`<a class="small-button" href="#karaoke/dubbing?tab=discover&project=${esc(p.id)}">참여 조합에서 배역 고르기</a>`:''}</section>
 ${mine&&!combo?`<section class="dubbing-panel"><h3>내 배역 · ${esc(mine.name)}</h3><button class="primary-button" data-dubbing-record-entry>${icon('mic')} 내 녹음·공개 설정</button><p class="dubbing-record-entry-status dubbing-muted" role="status">내 녹음을 공개하면 기본 1/${s.roles.length}로 유지돼요.</p></section>`:''}
 ${p.isOwner&&!combo?`<section id="dubbing-sound-panel" class="dubbing-panel">${dubbingSoundHTML(p.sound,true)}</section>`:''}
 ${p.isOwner?`<section class="dubbing-panel dubbing-manage"><h3>작품 관리</h3>${p.canEdit?`<a class="small-button" href="#dubbing/${esc(p.id)}?edit=1">대본 수정</a>`:''}${p.visibility==='private'?'<label class="dubbing-consent"><input id="dubbing-rights" type="checkbox"> 대본을 공개하고 함께 연기할 권한이 있습니다.</label><button class="primary-button" id="dubbing-publish">배역 모집 시작</button>':'<button class="small-button" id="dubbing-unpublish">비공개로 전환</button>'}<button class="small-button danger-button" id="dubbing-delete-project">대본 · 더빙 삭제</button><p class="dubbing-feedback" role="status"></p></section>`:''}</aside></div>${dubbingCommunityHTML(p)}`;
}
let castingPreviewContext=null;
function stopCastingPreview(){castingPreviewContext?.close().catch(()=>{});castingPreviewContext=null;}
window.addEventListener('hashchange',stopCastingPreview);
async function bindCastingDetail(p,root){
 root.querySelectorAll('[data-dc-filter]').forEach(b=>b.onclick=()=>{root.querySelectorAll('[data-dc-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));root.querySelectorAll('[data-dc-role-line]').forEach(line=>line.hidden=b.dataset.dcFilter!=='all'&&line.dataset.dcRoleLine!==b.dataset.dcFilter);});
 const panel=root.querySelector('#dc-complete-preview');if(!panel)return;
 try{
  const detail=await api('/api/dubbing/casting/'+p.id+'/lines','GET',undefined,{fresh:true});if(!panel.isConnected)return;
  panel.innerHTML=`<div class="dubbing-section-heading"><div><h2>${detail.members.length}/${p.roles.length} 목소리${detail.complete?'로 완성한 장면':' · 참여 중인 장면'}</h2><p class="dc-help">원래 대사 시간에 맞춰 배경과 목소리를 함께 들어보세요.</p></div><button class="small-button" id="dc-preview">${icon('ui-play-action')} 장면 미리듣기</button></div>${castingLinesHTML(detail.lines.filter(l=>l.audioUrl))}${detail.canRender&&!p.recording?.final?`<div class="dc-timing"><label>시작 위치 보정 <select id="dc-timing-line">${detail.lines.map((l,i)=>`<option value="${esc(l.id)}">${i+1}. ${esc(l.roleName)} · ${esc(l.text.slice(0,35))}</option>`).join('')}</select></label><label>초 <input id="dc-timing-offset" type="number" min="-1" max="1" step=".1" value="${detail.offsets[detail.lines[0].id]||0}"></label><button class="small-button" id="dc-save-timing">보정 저장</button></div><p class="dc-help">선택한 대사 시작을 ±1초 조정할 수 있어요. 다른 참여자의 녹음은 바꾸지 않아요.</p><label class="dubbing-consent"><input type="checkbox" id="dc-render-rights"> 참여자가 허용한 이 대본의 공동 작품으로 합성·저장·게시합니다.</label><button class="primary-button" id="dc-render">완성 오디오 저장·게시</button>`:p.recording?.final?.audioUrl?`<audio controls src="${esc(p.recording.final.audioUrl)}" aria-label="완성 더빙 듣기"></audio>`:p.recording?.final?`<p>${p.recording.final.state==='failed'?'최종 파일 생성에 실패했어요. 저장된 대사 녹음은 보존되어 있어요.':'최종 파일을 준비하고 있어요.'}</p>${p.recording.final.state==='failed'&&detail.canRender?'<label class="dubbing-consent"><input type="checkbox" id="dc-render-rights"> 참여 음성 이용허락에 따라 다시 합성합니다.</label><button class="primary-button" id="dc-render">오디오 생성 다시 요청</button>':''}<button class="small-button" id="dc-render-refresh">완성 상태 확인</button>`:''}<p class="dc-feedback" role="status"></p>`;
  bindCastingAudio(panel);const feedback=text=>{if(panel.isConnected)panel.querySelector('.dc-feedback').textContent=text;};
  panel.querySelector('#dc-render-refresh')?.addEventListener('click',()=>render());
  panel.querySelector('#dc-preview').onclick=async event=>{
   const b=event.currentTarget;if(castingPreviewContext){stopCastingPreview();b.innerHTML=icon('ui-play-action')+' 장면 미리듣기';return;}stopCastingAudio();audio.pause();b.disabled=true;
   try{const ctx=new AudioContext();castingPreviewContext=ctx;await ctx.resume();const tracks=[{url:detail.backgroundUrl,start:0,end:detail.duration},...detail.lines.filter(l=>l.audioUrl).map(l=>({url:l.audioUrl,start:Math.max(0,l.start+(detail.offsets[l.id]||0)),end:l.recordEnd+(detail.offsets[l.id]||0)}))];
    const decoded=await Promise.all(tracks.map(async t=>{const r=await fetch(t.url,{credentials:'same-origin'});if(!r.ok)throw Error('미리듣기 파일을 불러오지 못했어요.');return {...t,buffer:await ctx.decodeAudioData(await r.arrayBuffer())};}));
    if(!panel.isConnected||castingPreviewContext!==ctx){ctx.close().catch(()=>{});return;}const start=ctx.currentTime+.12;for(const t of decoded){const src=ctx.createBufferSource();src.buffer=t.buffer;src.connect(ctx.destination);src.start(start+t.start,0,Math.min(t.buffer.duration,detail.duration-t.start,t.end-t.start));}b.textContent='미리듣기 정지';setTimeout(()=>{if(castingPreviewContext===ctx){stopCastingPreview();if(b.isConnected)b.innerHTML=icon('ui-play-action')+' 장면 미리듣기';}},(detail.duration+.3)*1000);
   }catch(e){stopCastingPreview();feedback(e.message);}finally{b.disabled=false;}
  };
  const picker=panel.querySelector('#dc-timing-line'),offset=panel.querySelector('#dc-timing-offset');if(picker)picker.onchange=()=>{offset.value=detail.offsets[picker.value]||0;};
  panel.querySelector('#dc-save-timing')?.addEventListener('click',async event=>{const b=event.currentTarget;b.disabled=true;try{const d=await api('/api/dubbing/casting/'+p.id+'/timing','POST',{lineId:picker.value,offset:Number(offset.value)});detail.offsets=d.offsets;stopCastingPreview();feedback('대사 시작 위치를 저장했어요. 다시 미리 들어보세요.');}catch(e){feedback(e.message);}finally{b.disabled=false;}});
  panel.querySelector('#dc-render')?.addEventListener('click',async event=>{if(!panel.querySelector('#dc-render-rights').checked){feedback('참여 음성의 이용허락을 확인해주세요.');return;}const b=event.currentTarget;b.disabled=true;try{await api('/api/dubbing/casting/'+p.id+'/render','POST',{rightsAccepted:true});stopCastingPreview();await render();}catch(e){feedback(e.message);b.disabled=false;}});
 }catch(e){if(panel.isConnected)panel.innerHTML=`<p role="alert">${esc(e.message)}</p>`;}
}
